def flood_fill_detect_regions(grid):
    """
    Detect which background pixels are in enclosed regions.
    Returns a boolean mask where True = enclosed (should become 3)
    """
    from collections import deque

    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    result = [[False]*w for _ in range(h)]

    # Most frequent color is background
    from collections import Counter
    all_pixels = [grid[r][c] for r in range(h) for c in range(w)]
    bg = Counter(all_pixels).most_common(1)[0][0]

    # For each background pixel, check if it can reach the edge
    # If not, it's enclosed -> should become 3

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg:
                result[r][c] = True  # Assume enclosed, will update below

    # Flood fill from edge to mark non-enclosed bg pixels
    enqueue = list()
    for cc in range(w):
        if grid[0][cc] == bg:
            enqueue.append((0, cc))
        if grid[h-1][cc] == bg:
            enqueue.append((h-1, cc))
    for rr in range(1, h-1):
        if grid[rr][0] == bg:
            enqueue.append((rr, 0))
        if grid[rr][w-1] == bg:
            enqueue.append((rr, w-1))

    # Use BFS to find all connected bg reachable from edge
    edge_bg_set = set()
    while enqueue:
        rr, cc = enqueue[0]
        enqueue.pop(0)
        if (rr, cc) in edge_bg_set:
            continue
        edge_bg_set.add((rr, cc))
        result[rr][cc] = False  # Not enclosed

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = rr + dr, cc + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in edge_bg_set and grid[nr][nc] == bg:
                    enqueue.append((nr, nc))

    return result, bg

def apply_fill(grid, replace_mask):
    """Apply the fill transformation"""
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]
    for r in range(h):
        for c in range(w):
            if replace_mask[r][c]:
                result[r][c] = 3
    return result

